def calculate_tv_ratings(ratings_data, time_slot):
  # ratings_data is a dictionary with keys as time slots and values as dictionaries with keys as channels and values as ratings
  # time_slot is a string indicating the time slot to extract the ratings for
  result = {}
  for channel, ratings in ratings_data.get(time_slot, {}).items():
    result[channel] = ratings
  return result

